import{G as e,W as t,n,rt as r}from"./chunks/framework.OKfwtFe7.js";var i=JSON.parse(`{"title":"知识点整理","description":"","frontmatter":{},"headers":[],"relativePath":"knowledge.md","filePath":"knowledge.md","lastUpdated":1791575570000}`),a={name:`knowledge.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="知识点整理" tabindex="-1">知识点整理 <a class="header-anchor" href="#知识点整理" aria-label="Permalink to “知识点整理”">​</a></h1><p>调研五篇回答了「权威来源讲了什么、站内覆盖了多少、差异怎么处置」（见<a href="/hello-design-patterns/research/overview">调研总览</a>）。这一页把取证之后的结论收拢成一张知识点网，来源编号沿用<a href="/hello-design-patterns/research/overview#来源清单">调研总览的来源清单</a>的 S1–S28，想知道一条结论怎么查出来的，走条目里的链接回调研原文或站内落点页。</p><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to “核心概念”">​</a></h2><h3 id="gof-23-是基准线-不是边界" tabindex="-1">GoF 23 是基准线，不是边界 <a class="header-anchor" href="#gof-23-是基准线-不是边界" aria-label="Permalink to “GoF 23 是基准线，不是边界”">​</a></h3><p>23 个模式站内全部有正文页（创建型 5、结构型 7、行为型 11），覆盖核对 23/23。站内另收 GoF 没有的条目 24 个：多例、对象池、服务定位器、四个代理变体、智能指针、依赖注入，加上并发与特定领域两组。调研之后边界也划清了：聚合、限界上下文属于战略设计词汇，API 网关、Saga 属于分布式系统设计，都不在「对象级模式」的口径里，逐条理由记在<a href="/hello-design-patterns/research/coverage">覆盖核对与差异表</a>（来源：<a href="/hello-design-patterns/research/books">权威书籍与标准目录调研</a>，[S1]）。</p><h3 id="坏味道、反模式、模式是三层关系" tabindex="-1">坏味道、反模式、模式是三层关系 <a class="header-anchor" href="#坏味道、反模式、模式是三层关系" aria-label="Permalink to “坏味道、反模式、模式是三层关系”">​</a></h3><p>《重构》第 2 版的坏味道目录（过长函数、霰弹式修改、依恋情节）是代码层依据，AntiPatterns 与 Big Ball of Mud 给出架构与项目层的条目，模式是走出来的路。反模式篇按「形态、成因、代价、怎么走出来」四段写，段落结构沿用 SourceMaking 的条目骨架（[S6][S7][S17]）。</p><h3 id="solid-的出处链要认-2002-年那本" tabindex="-1">SOLID 的出处链要认 2002 年那本 <a class="header-anchor" href="#solid-的出处链要认-2002-年那本" aria-label="Permalink to “SOLID 的出处链要认 2002 年那本”">​</a></h3><p>五原则首见于 Martin 2002 年的《Agile Software Development: Principles, Patterns, and Practices》[S4]，Clean Architecture [S3] 把它归纳进依赖规则。站内只在<a href="/hello-design-patterns/evolution/solid">SOLID 与依赖规则</a>里讲依赖方向，架构分层与组件级三原则暂不单独成篇，理由是与「模式」口径的边界要先立住（来源：<a href="/hello-design-patterns/research/books">权威书籍调研</a> §3）。</p><h3 id="组合优于继承在-go-和前端是语言默认" tabindex="-1">组合优于继承在 Go 和前端是语言默认 <a class="header-anchor" href="#组合优于继承在-go-和前端是语言默认" aria-label="Permalink to “组合优于继承在 Go 和前端是语言默认”">​</a></h3><p>Go 没有继承，复用靠结构体嵌入加小接口；Vue 组合式 API 把同一功能的逻辑、状态、生命周期收进一个函数，React 用组件嵌套加自定义 Hook 收口。三处是同一原则在不同平台上的落地，都写在<a href="/hello-design-patterns/evolution/composition-over-inheritance">组合式设计</a>（[S21][S22][S23]）。</p><h3 id="稳定性模式从-release-it-来-熔断器应用面最广" tabindex="-1">稳定性模式从 Release It! 来，熔断器应用面最广 <a class="header-anchor" href="#稳定性模式从-release-it-来-熔断器应用面最广" aria-label="Permalink to “稳定性模式从 Release It! 来，熔断器应用面最广”">​</a></h3><p>熔断器同时服务限流、降级、故障隔离三个场景，现在是网关与 RPC 客户端的标配：Resilience4j、Polly、Sentinel 的熔断器是同一个模型——统计窗口内失败率超阈值就直接失败，不再打下游。同书其余三条也已补齐（<a href="/hello-design-patterns/evolution/bulkhead">隔舱</a>、<a href="/hello-design-patterns/evolution/timeout">超时</a>、<a href="/hello-design-patterns/evolution/retry">重试</a>），四条各管一段：隔舱限制同时占用，超时给单次调用限时，重试恢复瞬时故障，熔断器在故障持续时断闸；稳态讲&quot;每个可消耗的资源都要有补充机制&quot;，属容量纪律，不单独成篇 [S12]。</p><h3 id="有些模式在有的语言里根本不用写" tabindex="-1">有些模式在有的语言里根本不用写 <a class="header-anchor" href="#有些模式在有的语言里根本不用写" aria-label="Permalink to “有些模式在有的语言里根本不用写”">​</a></h3><p>策略在 Java 传 <code>Function</code>、C++ 传 <code>std::function</code> 或模板参数、TypeScript 传函数属性，四者都不需要为每个算法建子类。观察者在浏览器里就是 <code>EventTarget</code> 的 <code>addEventListener</code> [S28]，动态代理在 JavaScript 里是语言内置的 <code>Proxy</code> 对象。语言吃掉模式是常态，正文示例按语言习惯写，不硬造类图（来源：<a href="/hello-design-patterns/research/applications">应用场景与语言落地</a>）。</p><h2 id="权威书籍要点" tabindex="-1">权威书籍要点 <a class="header-anchor" href="#权威书籍要点" aria-label="Permalink to “权威书籍要点”">​</a></h2><p>15 本书的逐本对照在<a href="/hello-design-patterns/research/books">权威书籍与标准目录调研</a>，这里是收拢后的定位表：</p><table tabindex="0"><thead><tr><th>书</th><th>作者 / 出版</th><th>对应知识点</th></tr></thead><tbody><tr><td>Design Patterns（GoF）[S1]</td><td>Gamma 等，Addison-Wesley，1994</td><td>23 模式基准线，创建型 5、结构型 7、行为型 11</td></tr><tr><td>Head First 设计模式（第 2 版）[S2]</td><td>Freeman 等，O&#39;Reilly，2020</td><td>案例教学顺序；观察者章讲开闭原则，第 2 版加 Lambda 写法</td></tr><tr><td>Clean Architecture [S3]</td><td>Robert C. Martin，2017</td><td>SOLID、依赖规则、组件级三原则</td></tr><tr><td>Agile SW Development [S4]</td><td>Robert C. Martin，2002</td><td>SOLID 的原始出处</td></tr><tr><td>Patterns of Enterprise Application Architecture [S5]</td><td>Martin Fowler，2002</td><td>事务脚本、活动记录、数据映射器、仓储、单元工作；领域逻辑四式与数据源四式的分层</td></tr><tr><td>Refactoring（第 2 版）[S6]</td><td>Martin Fowler，2018</td><td>坏味道目录，反模式篇的代码层依据</td></tr><tr><td>AntiPatterns [S7]</td><td>Brown 等，Wiley，1998</td><td>金锤子、意面代码的出处</td></tr><tr><td>Big Ball of Mud [S8]</td><td>Foote、Yoder，PLoP 1997</td><td>大泥球的原始论文</td></tr><tr><td>POSA 卷 1、卷 2 [S9]</td><td>Buschmann 等，Wiley</td><td>分层、管道-过滤器、反应器、主动器、主动对象</td></tr><tr><td>Enterprise Integration Patterns [S10]</td><td>Hohpe、Woolf，2002</td><td>消息通道、路由、转换；是否开「集成模式」分区待定</td></tr><tr><td>Domain-Driven Design [S11]</td><td>Eric Evans，2003</td><td>战略设计词汇，本仓不收，理由见差异表</td></tr><tr><td>Release It!（第 2 版）[S12]</td><td>Nygard，2018</td><td>熔断器、隔舱、超时、重试、稳态</td></tr><tr><td>Microservices Patterns [S13]</td><td>Richardson，2018</td><td>API 网关、Saga、事件溯源的选题来源</td></tr><tr><td>Refactoring to Patterns [S14]</td><td>Kerievsky，2004</td><td>从坏味道到模式的演进路径</td></tr><tr><td>Kubernetes Patterns [S15]</td><td>Ibryam、Huß，2019</td><td>容器平台模式，选题来源</td></tr></tbody></table><p>两本给过额外要求：Head First 的单例代价讨论（全局状态、测试困难、序列化与反射破坏）由<a href="/hello-design-patterns/anti-patterns/god-object">神对象</a>与<a href="/hello-design-patterns/anti-patterns/golden-hammer">金锤子</a>承接反面视角；PoEAA 的领域逻辑四式里只有事务脚本此前缺页，本次补成<a href="/hello-design-patterns/other/transaction-script">事务脚本</a>并与<a href="/hello-design-patterns/anti-patterns/anemic-domain-model">贫血模型</a>对照，数据源四式由 <a href="/hello-design-patterns/other/orm">ORM 篇</a>覆盖，不重复成篇。</p><h2 id="官方文档要点" tabindex="-1">官方文档要点 <a class="header-anchor" href="#官方文档要点" aria-label="Permalink to “官方文档要点”">​</a></h2><p>8 个官方文档与 3 个社区站点的核对在<a href="/hello-design-patterns/research/official-docs">官方与社区文档调研</a>，口径要点收拢如下，入口链接按调研清单登记的官方域名挂出：</p><table tabindex="0"><thead><tr><th>来源</th><th>入口</th><th>要点</th></tr></thead><tbody><tr><td>Java SE <code>java.util.concurrent</code> [S19]</td><td><a href="https://docs.oracle.com/" target="_blank" rel="noreferrer">docs.oracle.com</a></td><td>并发篇术语基准；<code>Future.get()</code> 是阻塞取值，组合与回调要 <code>CompletableFuture</code>；<code>Semaphore</code> 的 <code>acquire</code> 可被中断，拿到许可后才 <code>release</code></td></tr><tr><td>C++ Core Guidelines [S20]</td><td><a href="https://isocpp.github.io/CppCoreGuidelines/" target="_blank" rel="noreferrer">isocpp.github.io</a></td><td>资源用 RAII 表达；<code>unique_ptr</code>/<code>shared_ptr</code> 参数传递按 R.30/R.31；站内示例按「值传递 + 移动」写</td></tr><tr><td>Go 官方文档 [S21]</td><td><a href="https://go.dev/" target="_blank" rel="noreferrer">go.dev</a></td><td>无继承，接口隐式实现加结构体嵌入；<code>context.Context</code> 当第一参数传超时与取消；pipeline 的 <code>close</code>、<code>range</code>、<code>select</code> 写法以官方博客为准</td></tr><tr><td>Vue.js 文档 [S22]</td><td><a href="https://vuejs.org/" target="_blank" rel="noreferrer">vuejs.org</a></td><td>组合式 API：逻辑复用靠函数返回值组合，不靠 mixin</td></tr><tr><td>React 文档 [S23]</td><td><a href="https://react.dev/" target="_blank" rel="noreferrer">react.dev</a></td><td>组件嵌套 + props 组合，状态提升，重复逻辑用自定义 Hook 收口</td></tr><tr><td>.NET 设计指南 [S24]</td><td><a href="https://learn.microsoft.com/" target="_blank" rel="noreferrer">learn.microsoft.com</a></td><td>依赖走构造函数注入，扩展点用接口不用虚方法基类</td></tr><tr><td>Spring 文档 [S27]</td><td><a href="https://docs.spring.io/" target="_blank" rel="noreferrer">docs.spring.io</a></td><td>控制反转是容器负责组装；与<a href="/hello-design-patterns/creational/service-locator">服务定位器</a>的区别在谁发起装配</td></tr><tr><td>MDN [S28]</td><td><a href="https://developer.mozilla.org/" target="_blank" rel="noreferrer">developer.mozilla.org</a></td><td><code>Proxy</code>、迭代器协议、<code>EventTarget</code> 是前端三个语言内置的模式落点</td></tr><tr><td>Refactoring.Guru [S16]</td><td><a href="https://refactoring.guru/" target="_blank" rel="noreferrer">refactoring.guru</a></td><td>三分法与代理四变体的命名一致；空对象它单列、本仓并入策略篇一节</td></tr><tr><td>SourceMaking [S17]</td><td><a href="https://sourcemaking.com/" target="_blank" rel="noreferrer">sourcemaking.com</a></td><td>反模式四段式骨架的出处</td></tr><tr><td>iluwatar/java-design-patterns [S18]</td><td><a href="https://github.com/iluwatar/java-design-patterns" target="_blank" rel="noreferrer">github.com</a></td><td>收录取舍以「有没有书籍出处」为准：熔断有（Release It!），类别对象、环境对象这类纯社区条目不收</td></tr></tbody></table><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to “应用场景”">​</a></h2><p>场景到模式的完整对照表在<a href="/hello-design-patterns/research/applications">应用场景与语言落地</a>，六组场景的骨架：</p><table tabindex="0"><thead><tr><th>场景</th><th>代表模式</th><th>落地形态</th></tr></thead><tbody><tr><td>对象创建与装配</td><td>抽象工厂、建造者、单例、对象池</td><td>Java/C# 由容器装配，Go 写在 <code>main</code> 里</td></tr><tr><td>接口适配与访问控制</td><td>适配器、外观、代理四变体、装饰</td><td>Java <code>java.lang.reflect.Proxy</code>、JS <code>Proxy</code>、C++ 包装类</td></tr><tr><td>行为与流程</td><td>策略、模板方法、观察者、责任链、状态、访问者</td><td>中间件栈是责任链在 Web 框架的形态</td></tr><tr><td>并发与异步</td><td>线程池、读写锁、工作窃取、生产者-消费者、Future</td><td>术语以 j.u.c 文档为准</td></tr><tr><td>数据与分层</td><td>ORM、事务脚本、事件溯源、MVC/MVVM</td><td>事件溯源记过程，备忘录记瞬间</td></tr><tr><td>分布式与云上</td><td>熔断器、隔舱、超时、重试</td><td>Resilience4j、Polly、Sentinel 同一模型，在 Resilience4j 里是并列的四个模块</td></tr></tbody></table><p>多语言落地四条约定：多态按语言习惯写（Java/C# 接口、C++ 抽象类、Go 小接口加嵌入）；复用逻辑统一改写成组合；单例的代价 Java/C# 最明显，Go 包级变量可测性同样差；线程模型决定并发篇示例（Java 线程池、C++ <code>std::jthread</code> 加 <code>std::stop_token</code>、Go goroutine 加 channel）。</p><h2 id="常见坑与误区" tabindex="-1">常见坑与误区 <a class="header-anchor" href="#常见坑与误区" aria-label="Permalink to “常见坑与误区”">​</a></h2><table tabindex="0"><thead><tr><th>坑</th><th>事实</th><th>展开页</th></tr></thead><tbody><tr><td><code>Future</code> 当异步组合用</td><td><code>Future.get()</code> 阻塞，组合与回调要 <code>CompletableFuture</code></td><td><a href="/hello-design-patterns/concurrency/future">Future 模式</a></td></tr><tr><td><code>Semaphore</code> 先 release 后 acquire</td><td><code>acquire</code> 可被中断，许可必须在持有后才释放，顺序反了等于没限制</td><td><a href="/hello-design-patterns/concurrency/semaphore">信号量模式</a></td></tr><tr><td>C++ 手写自赋值判断</td><td>旧版写法已被 copy-and-swap 取代，与 Guidelines 的资源管理意图一致</td><td><a href="/hello-design-patterns/structural/smart-pointer">智能指针模式</a></td></tr><tr><td>跨语言硬译模式</td><td>Go 的模板方法没有抽象类，用接口加嵌入表达同一骨架，照搬 Java 类图写不成立</td><td><a href="/hello-design-patterns/behavioral/template-method">模板方法模式</a></td></tr><tr><td>C++ 手写双分派表</td><td>惯用 <code>std::variant</code> 加 <code>std::visit</code>，分支交给标准库</td><td><a href="/hello-design-patterns/behavioral/visitor">访问者模式</a></td></tr><tr><td>前端示例写旧范式</td><td>Vue 2 选项式与 React class 组件不写，统一组合式 API 与函数组件</td><td><a href="/hello-design-patterns/evolution/composition-over-inheritance">组合式设计</a></td></tr><tr><td>非幂等操作直接重试</td><td>扣款重试一次就是两笔扣款，先加幂等键或先查结果再重试</td><td><a href="/hello-design-patterns/evolution/retry">重试模式</a></td></tr><tr><td>超时设得比下游 P99 还短</td><td>正常慢请求被杀，下游副作用却已发生，读超时按下游 P99 的 1.5–2 倍设</td><td><a href="/hello-design-patterns/evolution/timeout">超时模式</a></td></tr><tr><td>空对象当 Optional 用</td><td>空对象是&quot;有但什么都不做&quot;，调用方无感；Optional 是&quot;可能没有&quot;，调用方仍要处理缺失分支，两者解决的问题不同</td><td><a href="/hello-design-patterns/behavioral/strategy">策略模式</a></td></tr></tbody></table><h2 id="覆盖核对结论" tabindex="-1">覆盖核对结论 <a class="header-anchor" href="#覆盖核对结论" aria-label="Permalink to “覆盖核对结论”">​</a></h2><p>逐条核对表在<a href="/hello-design-patterns/research/coverage">覆盖核对与差异表</a>，数字收拢：</p><ul><li>GoF 23/23 全部有正文页，不需要补。</li><li>调研得出缺口 14 项，全部补成新篇：反模式 6、现代演进 4、并发 3（线程池、读写锁、工作窃取，概览早已声明但缺页）、其他 1（事务脚本）。</li><li>调研到但核对当时不新增 12 项，每项都写了理由：分层与管道-过滤器属架构风格需先定口径，聚合与限界上下文不在「模式」口径内。隔舱、超时、重试、仓储与单元工作、空对象 5 项已按口径补齐（2026-10-10），稳态定为不单独成篇，其余 9 行维持暂不收录。</li><li>站内交叉引用不一致 6 处，随本次修订（智能指针条目错字、概览漏列 DSL 与并发三篇、参考页索引缺三组书目）。</li><li>站内 Markdown 从 56 篇增到 75 篇，模式正文 47 → 61；2026-10-10 稳定性三篇后为 78 篇，模式正文 64；仓储与单元工作后为 79 篇，模式正文 65。</li></ul><h2 id="来源与口径" tabindex="-1">来源与口径 <a class="header-anchor" href="#来源与口径" aria-label="Permalink to “来源与口径”">​</a></h2><ul><li>来源编号 S1–S28 的完整清单在<a href="/hello-design-patterns/research/overview#来源清单">调研总览</a>，书籍出版信息以该清单为准，改版时同步更新。</li><li>核对方法：书目目录拆条目，逐条对 <code>docs/</code> 下的文件；判定只有三档——有正文页、声明未落地、缺口。核对时间 2026-10-08。</li><li>验收方式：站内链接一律绝对路径，<code>npm run docs:build</code> 的死链检查兜底。</li></ul><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to “参考资料”">​</a></h2><ul><li><a href="/hello-design-patterns/research/overview">调研总览</a>——范围、方法、结论与 28 条来源清单</li><li><a href="/hello-design-patterns/research/books">权威书籍与标准目录</a>——15 本书逐本对照</li><li><a href="/hello-design-patterns/research/official-docs">官方与社区文档</a>——8 个官方文档与 3 个社区站点</li><li><a href="/hello-design-patterns/research/applications">应用场景与语言落地</a>——场景到 API 的对照表</li><li><a href="/hello-design-patterns/research/coverage">覆盖核对与差异表</a>——三张表：覆盖、缺口、交叉引用修订</li></ul>`,35)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};